  ('620baad0-ce27-40d4-ab9e-81da720e431a', 'b4c5d6e7-8f9a-4b54-9c34-4d5e6f7a8b64', '74ddd65b-898e-440d-8c50-0d02197492de', 'concept'::public.curated_course_node_type, 'Sixth Amendment, counsel, speedy trial, public trial, jury trial, confrontation, plea bargaining', null, 2),
