  ('269a9d42-a99a-4b18-b8d0-739fe9c0289b', 'b4c5d6e7-8f9a-4b54-9c34-4d5e6f7a8b64', null, 'topic'::public.curated_course_node_type, 'Civil Rights, Equal Protection, and Democratic Inclusion', 'Civil rights concern equal treatment and meaningful inclusion in public life. Students study law, movements, institutions, and policy tools used to challenge exclusion.', 4),
  ('c59522bc-2700-4db3-baea-785584ebbb11', 'b4c5d6e7-8f9a-4b54-9c34-4d5e6f7a8b64', '269a9d42-a99a-4b18-b8d0-739fe9c0289b', 'subtopic'::public.curated_course_node_type, 'Equal Protection and Anti-Discrimination Law', 'Students learn the constitutional and statutory tools used to evaluate unequal treatment.', 0),
