  ('5a2660cb-507f-4510-b5df-e078d1e73aa6', 'b4c5d6e7-8f9a-4b54-9c34-4d5e6f7a8b64', null, 'topic'::public.curated_course_node_type, 'Public Opinion, Political Socialization, Ideology, and Polarization', 'This section teaches students how citizens develop beliefs and how those beliefs are measured. Students learn to read opinion data carefully and connect opinion to democratic responsiveness.', 5),
  ('af10d91f-a934-446a-a528-c6725839540b', 'b4c5d6e7-8f9a-4b54-9c34-4d5e6f7a8b64', '5a2660cb-507f-4510-b5df-e078d1e73aa6', 'subtopic'::public.curated_course_node_type, 'Political Socialization and Political Identity', 'Students learn how people acquire political attitudes and identities over time.', 0),
