  ('16936e8f-7c58-4d11-8a00-1a09e2c5e3f2', 'b4c5d6e7-8f9a-4b54-9c34-4d5e6f7a8b64', null, 'topic'::public.curated_course_node_type, 'Political Participation, Voting Behavior, and Elections', 'Elections are central to representation, but participation is uneven and shaped by rules. Students learn how people participate, why they vote, and how electoral systems translate votes into power.', 6),
  ('11ea4673-ffba-404b-af36-a371390507d3', 'b4c5d6e7-8f9a-4b54-9c34-4d5e6f7a8b64', '16936e8f-7c58-4d11-8a00-1a09e2c5e3f2', 'subtopic'::public.curated_course_node_type, 'Forms of Political Participation', 'Students broaden participation beyond voting and evaluate different forms of civic action.', 0),
  ('cb3320ce-076a-4bae-8f00-38fc76fbc980', 'b4c5d6e7-8f9a-4b54-9c34-4d5e6f7a8b64', '11ea4673-ffba-404b-af36-a371390507d3', 'concept'::public.curated_course_node_type, 'Voting, volunteering, donating, protesting, contacting officials, attending meetings, petitioning, boycotting, mutual aid', null, 0),
