  ('b5ae1e9f-5e45-4f14-94f9-856ab4501dc4', 'b4c5d6e7-8f9a-4b54-9c34-4d5e6f7a8b64', '11ea4673-ffba-404b-af36-a371390507d3', 'concept'::public.curated_course_node_type, 'Political efficacy, mobilization, resources, recruitment, social networks, and participation gaps', null, 2),
