  ('460f586a-6c33-4331-9775-200799b4f4fd', 'b4c5d6e7-8f9a-4b54-9c34-4d5e6f7a8b64', null, 'topic'::public.curated_course_node_type, 'Political Parties, Campaigns, Interest Groups, and Lobbying', 'This section covers linkage institutions that organize political conflict. Students learn how parties, campaigns, and organized interests shape choices, agendas, and policy outcomes.', 7),
